    <div class="table-wrap"><table class="student-table"><thead><tr><th>Student · synthetic</th><th>Age at enrollment</th><th>Course reference</th><th>Admission grade</th><th>Previous qualification grade</th><th>Demo score</th><th>Review band</th><th>Details</th></tr></thead><tbody id="student-table-body"></tbody></table></div>
